import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var l, r int64
	fmt.Fscan(in, &l, &r)

	var answer int64
	low, power := int64(1), int64(10)

	for low <= r {
		m := power - 1
		left := l
		if left < low {
			left = low
		}
		right := r
		if right > m {
			right = m
		}

		if left <= right {
			for _, n := range []int64{m / 2, m/2 + 1} {
				if n < left {
					n = left
				}
				if n > right {
					n = right
				}
				weight := n * (m - n)
				if weight > answer {
					answer = weight
				}
			}
		}

		low *= 10
		power *= 10
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
