package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var l, r int64
	fmt.Fscan(in, &l, &r)

	var answer int64
	var power int64 = 10

	for digits := 1; digits <= 10; digits++ {
		minN := power / 10
		if digits == 1 {
			minN = 1
		}
		maxN := power - 1

		lo := l
		if lo < minN {
			lo = minN
		}
		hi := r
		if hi > maxN {
			hi = maxN
		}

		if lo <= hi {
			mid := maxN / 2
			if mid < lo {
				mid = lo
			} else if mid > hi {
				mid = hi
			}

			candidates := []int64{lo, hi, mid}
			if mid+1 <= hi {
				candidates = append(candidates, mid+1)
			}

			for _, n := range candidates {
				weight := n * (maxN - n)
				if weight > answer {
					answer = weight
				}
			}
		}

		power *= 10
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var l, r int64
	fmt.Fscan(in, &l, &r)

	var answer int64
	start, power := int64(1), int64(10)

	for start <= r {
		end := power - 1
		lo, hi := l, r

		if lo < start {
			lo = start
		}
		if hi > end {
			hi = end
		}

		if lo <= hi {
			mid := end / 2
			n := mid
			if n < lo {
				n = lo
			}
			if n > hi {
				n = hi
			}

			weight := n * (end - n)
			if weight > answer {
				answer = weight
			}
		}

		start = power
		power *= 10
	}

	fmt.Fprintln(out, answer)
}
